-- Singapore deep-dive page translations: page fields, stats, cards,
-- lifecycle card + statuses, steps, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Peppol, en transición de 4 esquinas → 5 esquinas', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los detalles técnicos de PINT-SG, las fechas del despliegue por fases y los requisitos de reporte de la IRAS continúan evolucionando — confirme los requisitos actuales directamente con la IRAS o la IMDA antes de construir una integración.', 'Singapur está aplicando uno de los calendarios de implantación por fases más largos y detallados de este rastreador — seis años, fraccionados tanto por estado de constitución como por banda de facturación.', 'SG Peppol BIS Billing 3.0 es una extensión nacional genuina del estándar europeo — no un formato local construido desde cero.', 'InvoiceNow está transitando deliberadamente de una red de intercambio pura a una red de reporte fiscal — la actualización de "5 esquinas" añade a la IRAS como participante genuino, no solo como observador.', 'El registro depende de obtener un ID Peppol antes de tratar con la IRAS — trátelo como el verdadero primer paso, no como una formalidad.', 'El enfoque de Singapur es notablemente gradual y consultivo — una postura genuinamente distinta de los mandatos más rápidos en otras partes de este rastreador.' FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Peppol, im Übergang von 4-Corner zu 5-Corner', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Technische Details zu PINT-SG, Termine des stufenweisen Rollouts und IRAS-Meldepflichten entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt bei der IRAS oder der IMDA, bevor Sie eine Integration aufbauen.', 'Singapur betreibt einen der längsten und detailliertesten stufenweisen Einführungspläne in diesem Tracker — sechs Jahre, aufgeteilt sowohl nach Gründungsstatus als auch nach Umsatzband.', 'SG Peppol BIS Billing 3.0 ist eine echte nationale Erweiterung des europäischen Standards — kein von Grund auf neu entwickeltes lokales Format.', 'InvoiceNow wandelt sich bewusst von einem reinen Austauschnetzwerk zu einem steuerlichen Meldenetzwerk — das "5-Corner"-Upgrade macht die IRAS zu einem echten Teilnehmer, nicht nur zu einem Beobachter.', 'Die Registrierung hängt davon ab, eine Peppol-ID zu erhalten, bevor Sie überhaupt mit der IRAS in Kontakt treten — behandeln Sie dies als den eigentlichen ersten Schritt, nicht als Formalität.', 'Singapurs Ansatz ist bemerkenswert schrittweise und konsultativ — eine wirklich andere Haltung als die schneller voranschreitenden Mandate anderswo in diesem Tracker.' FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Peppol, transition de 4 coins vers 5 coins', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les détails techniques de PINT-SG, les dates du déploiement échelonné et les exigences de déclaration de l''IRAS continuent d''évoluer — confirmez les exigences actuelles directement auprès de l''IRAS ou de l''IMDA avant de construire une intégration.', 'Singapour applique l''un des calendriers de déploiement échelonné les plus longs et les plus détaillés de ce tracker — six ans, découpés à la fois par statut de constitution et par tranche de chiffre d''affaires.', 'SG Peppol BIS Billing 3.0 est une véritable extension nationale de la norme européenne — pas un format local construit de toutes pièces.', 'InvoiceNow passe délibérément d''un réseau d''échange pur à un réseau de déclaration fiscale — la mise à niveau « 5 coins » fait de l''IRAS un véritable participant, pas seulement un observateur.', 'L''inscription dépend de l''obtention d''un identifiant Peppol avant même de traiter avec l''IRAS — considérez cela comme la véritable première étape, pas une formalité.', 'L''approche de Singapour est notablement graduelle et consultative — une posture véritablement différente des mandats plus rapides ailleurs dans ce tracker.' FROM countries WHERE name_en = 'Singapore';

