INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Formato', '[["Estándar actual", "SG Peppol BIS Billing 3.0"], ["Base", "Peppol BIS 3.0 europeo, extendido para requisitos específicos de Singapur"], ["Firma digital", "No se requiere del contribuyente"]]', 'A diferencia de los países con modelo de compensación, InvoiceNow no requiere que el contribuyente firme digitalmente las facturas — la seguridad, integridad y autenticidad están salvaguardadas por la red Peppol y los proveedores de Puntos de Acceso acreditados.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Format', '[["Aktueller Standard", "SG Peppol BIS Billing 3.0"], ["Basis", "Europäisches Peppol BIS 3.0, erweitert um Singapur-spezifische Anforderungen"], ["Digitale Signatur", "Vom Steuerpflichtigen nicht erforderlich"]]', 'Anders als in Ländern mit Clearing-Modell verlangt InvoiceNow keine digitale Signatur der Rechnungen durch den Steuerpflichtigen — Sicherheit, Integrität und Authentizität werden stattdessen durch das Peppol-Netzwerk und akkreditierte Access-Point-Anbieter gewährleistet.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Format', '[["Norme actuelle", "SG Peppol BIS Billing 3.0"], ["Base", "Peppol BIS 3.0 européen, étendu pour les exigences spécifiques à Singapour"], ["Signature numérique", "Non requise du contribuable"]]', 'Contrairement aux pays à modèle de contrôle, InvoiceNow n''exige pas du contribuable qu''il signe numériquement les factures — la sécurité, l''intégrité et l''authenticité sont plutôt garanties par le réseau Peppol et les fournisseurs de points d''accès agréés.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Elementos de datos obligatorios', '[["Identificadores de parte", "UEN del proveedor/cliente y números de registro GST (GSTN)"], ["Códigos fiscales", "Asignados a los códigos de categoría GST aprobados por la IRAS (Anexo E, Guía e-Tax)"], ["Entradas agregadas", "Indicadores especiales \"POS\" o \"PCP\" para compras en punto de venta/caja chica"]]', 'Mapear correctamente sus códigos fiscales internos a la lista estandarizada de categorías GST de la IRAS es uno de los pasos técnicos de mayor fricción — hacerlo mal marcará sus envíos.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Pflichtdatenelemente', '[["Parteikennungen", "Lieferanten-/Kunden-UEN und GST-Registrierungsnummern (GSTN)"], ["Steuercodes", "Zugeordnet zu den von der IRAS genehmigten GST-Kategoriecodes (Anhang E, e-Tax Guide)"], ["Aggregierte Einträge", "Spezielle „POS“- oder „PCP“-Kennzeichen für Point-of-Sale-/Portokassekäufe"]]', 'Die korrekte Zuordnung Ihrer internen Steuercodes zur standardisierten GST-Kategorieliste der IRAS ist einer der Schritte mit dem höchsten technischen Reibungspotenzial — machen Sie hier Fehler, werden Ihre Einreichungen markiert.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Éléments de données obligatoires', '[["Identifiants des parties", "UEN du fournisseur/client et numéros d''enregistrement GST (GSTN)"], ["Codes fiscaux", "Associés aux codes de catégorie GST approuvés par l''IRAS (annexe E, e-Tax Guide)"], ["Entrées agrégées", "Indicateurs spéciaux « POS » ou « PCP » pour les achats en point de vente/petite caisse"]]', 'Associer correctement vos codes fiscaux internes à la liste de catégories GST normalisée de l''IRAS est l''une des étapes techniques les plus délicates — une erreur ici fera signaler vos soumissions.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identificadores', '[["Base del ID Peppol", "Número de Entidad Único (UEN)"], ["También sustenta", "PayNow Corporate (el esquema de pago electrónico de Singapur)"], ["Empresas multi-entidad", "Cada entidad registrada en el GST necesita su propio ID Peppol"]]', 'Para grupos con múltiples entidades operativas, diseñe desde el principio un ID Peppol y una configuración de Punto de Acceso independientes por entidad — adaptar esto después de la puesta en marcha resulta genuinamente disruptivo.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Identifikatoren', '[["Basis der Peppol-ID", "Unique Entity Number (UEN)"], ["Liegt auch zugrunde", "PayNow Corporate (Singapurs E-Zahlungssystem)"], ["Unternehmen mit mehreren Einheiten", "Jede GST-registrierte Einheit benötigt ihre eigene Peppol-ID"]]', 'Konzipieren Sie für Gruppen mit mehreren operativen Einheiten von Anfang an eine separate Peppol-ID und Access-Point-Konfiguration pro Einheit — eine nachträgliche Anpassung nach dem Go-Live ist wirklich störend.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identifiants', '[["Base de l''identifiant Peppol", "Unique Entity Number (UEN)"], ["Sous-tend également", "PayNow Corporate (le système de paiement électronique de Singapour)"], ["Entreprises multi-entités", "Chaque entité enregistrée à la GST a besoin de son propre identifiant Peppol"]]', 'Pour les groupes disposant de plusieurs entités opérationnelles, concevez dès le départ un identifiant Peppol et une configuration de point d''accès distincts par entité — adapter cela après la mise en service est véritablement perturbateur.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Formato en evolución: PINT SG', '[["Campos ausentes en plantillas antiguas", "Códigos de tipo de suministro, importes de GST a nivel de línea, ID Peppol vinculados al UEN"]]', 'Si sus plantillas de factura se crearon antes del requisito de GST de InvoiceNow, espere brechas significativas frente a los nuevos requisitos de campos alineados con PINT-SG — audite en lugar de asumir compatibilidad.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Sich entwickelndes Format: PINT SG', '[["Felder, die in älteren Vorlagen fehlen", "Liefertyp-Codes, GST-Beträge auf Zeilenebene, UEN-verknüpfte Peppol-IDs"]]', 'Wenn Ihre Rechnungsvorlagen vor der GST-Anforderung von InvoiceNow erstellt wurden, erwarten Sie erhebliche Lücken gegenüber den neueren PINT-SG-konformen Feldanforderungen — prüfen Sie dies, statt Kompatibilität anzunehmen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Format en évolution : PINT SG', '[["Champs absents des anciens modèles", "Codes de type de fourniture, montants GST au niveau ligne, identifiants Peppol liés à l''UEN"]]', 'Si vos modèles de facture ont été créés avant l''exigence GST d''InvoiceNow, attendez-vous à des écarts significatifs par rapport aux nouvelles exigences de champs alignées sur PINT-SG — auditez plutôt que de présumer la compatibilité.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Gobernanza', '[["IMDA", "Autoridad Peppol de Singapur; define los Requisitos Específicos de la Autoridad Peppol (PASR)"], ["IRAS", "Recibe los datos de facturas reportados para la administración del GST"]]', 'La IMDA acredita a los proveedores de Puntos de Acceso/SMP; la IRAS es la autoridad fiscal que consume los datos que transmiten esos proveedores — dos funciones distintas que conviene mantener separadas en su modelo mental.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Governance', '[["IMDA", "Singapurs Peppol-Autorität; definiert die Peppol Authority Specific Requirements (PASR)"], ["IRAS", "Erhält die gemeldeten Rechnungsdaten für die GST-Verwaltung"]]', 'Die IMDA akkreditiert die Access-Point-/SMP-Dienstanbieter; die IRAS ist die Steuerbehörde, die die von diesen Anbietern übermittelten Daten nutzt — zwei unterschiedliche Rollen, die es sich lohnt, gedanklich getrennt zu halten.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Gouvernance', '[["IMDA", "Autorité Peppol de Singapour ; définit les exigences spécifiques de l''autorité Peppol (PASR)"], ["IRAS", "Reçoit les données de facturation déclarées pour l''administration de la GST"]]', 'L''IMDA agrée les fournisseurs de points d''accès/SMP ; l''IRAS est l''autorité fiscale qui exploite les données transmises par ces fournisseurs — deux rôles distincts qu''il convient de garder séparés dans votre modèle mental.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Plazo de envío', '[["Fecha límite", "La anterior entre la fecha de presentación de la declaración de GST o el plazo estatutario de esa declaración"]]', 'Esto vincula su cadencia de transmisión de InvoiceNow directamente a su calendario de presentación de GST existente en lugar de requerir un plazo separado en tiempo real que rastrear.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Übermittlungsfrist', '[["Frist", "Der frühere Zeitpunkt zwischen dem GST-Erklärungstermin oder der gesetzlichen Frist für diese Erklärung"]]', 'Dies koppelt Ihren InvoiceNow-Übermittlungsrhythmus direkt an Ihren bestehenden GST-Meldekalender, statt eine separate Echtzeitfrist zu erfordern, die Sie nachverfolgen müssen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Délai de soumission', '[["Échéance", "La plus proche entre la date de dépôt de la déclaration GST ou l''échéance statutaire de cette déclaration"]]', 'Cela lie votre cadence de transmission InvoiceNow directement à votre calendrier de déclaration GST existant plutôt que d''exiger une échéance en temps réel distincte à suivre.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Roles: IRSP vs. AP', '[["IRSP", "Proveedor de Solución Lista para InvoiceNow — proporciona el software de contabilidad"], ["AP", "Punto de Acceso — habilita la conectividad de red"]]', 'A menudo son el mismo proveedor comercial en la práctica, pero son conceptualmente funciones distintas — conviene aclarar con su proveedor qué función están desempeñando realmente para usted.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Rollen: IRSP vs. AP', '[["IRSP", "InvoiceNow-Ready Solution Provider — stellt die Buchhaltungssoftware bereit"], ["AP", "Access Point — ermöglicht die Netzwerkanbindung"]]', 'In der Praxis handelt es sich oft um denselben kommerziellen Anbieter, konzeptionell sind es jedoch unterschiedliche Rollen — es lohnt sich, mit Ihrem Anbieter zu klären, welche Funktion er tatsächlich für Sie erfüllt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Rôles : IRSP vs. AP', '[["IRSP", "InvoiceNow-Ready Solution Provider — fournit le logiciel comptable"], ["AP", "Point d''accès — permet la connectivité réseau"]]', 'Il s''agit souvent du même fournisseur commercial en pratique, mais ce sont des rôles conceptuellement distincts — il convient de clarifier avec votre fournisseur quelle fonction il assure réellement pour vous.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'El flujo de intercambio', NULL, 'La factura llega al cliente, y se transmite una copia a la IRAS de forma simultánea o poco después — a través de la misma red InvoiceNow, no un canal de presentación separado.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Der Austauschablauf', NULL, 'Die Rechnung erreicht den Kunden, und eine Kopie wird gleichzeitig oder kurz danach an die IRAS übermittelt — über dasselbe InvoiceNow-Netzwerk, nicht über einen separaten Meldekanal.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Le flux d''échange', NULL, 'La facture parvient au client, et une copie est transmise à l''IRAS simultanément ou peu après — via le même réseau InvoiceNow, et non un canal de dépôt distinct.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Singapore';

