INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga su ID Peppol', 'Trabaje con su proveedor IRSP o AP elegido para registrarse en el Directorio Peppol de Singapur usando su UEN — este es un requisito previo para cualquier transmisión de InvoiceNow, separado de su registro ACRA o de su propio número de registro de GST.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie Ihre Peppol-ID', 'Arbeiten Sie mit Ihrem gewählten IRSP- oder AP-Anbieter zusammen, um sich mit Ihrer UEN im SG-Peppol-Verzeichnis zu registrieren — dies ist eine Voraussetzung für jede InvoiceNow-Übermittlung, getrennt von Ihrer ACRA-Registrierung oder Ihrer GST-Registrierungsnummer selbst.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez votre identifiant Peppol', 'Travaillez avec votre fournisseur IRSP ou AP choisi pour vous inscrire au répertoire SG Peppol à l''aide de votre UEN — c''est un prérequis pour toute transmission InvoiceNow, distinct de votre enregistrement ACRA ou de votre numéro d''enregistrement GST lui-même.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Contrate un Punto de Acceso acreditado por la IMDA (si usa software personalizado/interno)', 'Si no está usando una Solución Lista para InvoiceNow lista para usar, necesitará un proveedor AP acreditado específicamente para establecer conectividad de red segura.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Engagieren Sie einen IMDA-akkreditierten Access Point (bei individueller/interner Software)', 'Wenn Sie keine vorgefertigte InvoiceNow-Ready-Lösung verwenden, benötigen Sie speziell einen akkreditierten AP-Anbieter, um eine sichere Netzwerkanbindung herzustellen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Faites appel à un point d''accès agréé par l''IMDA (si vous utilisez un logiciel personnalisé/interne)', 'Si vous n''utilisez pas une solution prête pour InvoiceNow sur étagère, vous aurez besoin d''un fournisseur AP agréé spécifiquement pour établir une connectivité réseau sécurisée.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Asigne sus códigos fiscales internos a los códigos de categoría GST de la IRAS', 'Use el Anexo E de la Guía e-Tax de la IRAS como referencia — cada transacción necesita una categorización precisa antes del envío.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ordnen Sie Ihre internen Steuercodes den GST-Kategoriecodes der IRAS zu', 'Verwenden Sie Anhang E des e-Tax Guide der IRAS als Referenz — jede Transaktion benötigt vor der Einreichung eine korrekte Kategorisierung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Associez vos codes fiscaux internes aux codes de catégorie GST de l''IRAS', 'Utilisez l''annexe E du guide e-Tax de l''IRAS comme référence — chaque transaction nécessite une catégorisation précise avant soumission.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que su Solución Lista para InvoiceNow está integrada con la IRAS', 'Asegúrese de que se conecte mediante tecnología API a través de Puntos de Acceso acreditados por la IMDA, permitiendo la transmisión automatizada en tiempo real o regular de datos de facturas a la IRAS.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass Ihre InvoiceNow-Ready-Lösung IRAS-integriert ist', 'Stellen Sie sicher, dass sie über API-Technologie durch IMDA-akkreditierte Access Points verbunden ist und eine Echtzeit- oder regelmäßige automatisierte Übermittlung von Rechnungsdaten an die IRAS ermöglicht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez que votre solution prête pour InvoiceNow est intégrée à l''IRAS', 'Assurez-vous qu''elle se connecte via une technologie API à travers des points d''accès agréés par l''IMDA, permettant une transmission automatisée en temps réel ou régulière des données de facturation à l''IRAS.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Planifique con antelación una arquitectura de ID Peppol multi-entidad', 'Si opera múltiples entidades registradas en el GST, diseñe su configuración de ID Peppol y Punto de Acceso por entidad desde el principio, en lugar de descubrir el requisito durante las pruebas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Planen Sie frühzeitig eine Multi-Entity-Peppol-ID-Architektur', 'Wenn Sie mehrere GST-registrierte Einheiten betreiben, gestalten Sie Ihre Peppol-ID- und Access-Point-Konfiguration von Anfang an pro Einheit, statt die Anforderung erst während der Tests zu entdecken.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Planifiez tôt une architecture d''identifiant Peppol multi-entités', 'Si vous exploitez plusieurs entités enregistrées à la GST, concevez votre configuration d''identifiant Peppol et de point d''accès par entité dès le départ, plutôt que de découvrir l''exigence lors des tests.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Compruebe en qué punto del despliegue por fases se encuentra', 'Si aún no está obligatoriamente dentro del alcance, use la fase voluntaria para desarrollar familiaridad institucional antes de su hito específico de 2028–2031.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie, wo Sie im stufenweisen Rollout stehen', 'Wenn Sie noch nicht verpflichtend im Anwendungsbereich sind, nutzen Sie die freiwillige Phase, um institutionelle Vertrautheit vor Ihrem spezifischen Meilenstein 2028–2031 aufzubauen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez où vous vous situez dans le déploiement échelonné', 'Si vous n''êtes pas encore obligatoirement dans le champ d''application, utilisez la phase volontaire pour développer une familiarité institutionnelle avant votre jalon spécifique de 2028-2031.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Singapore' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🐢 Un margen deliberadamente largo', NULL, NULL, 'Seis años entre la primera cohorte obligatoria (nov. 2025) y el despliegue completo (abr. 2031) es uno de los períodos de implantación más largos de este rastreador — Singapur parece priorizar una adopción fluida sobre la velocidad.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🐢 Ein bewusst langer Vorlauf', NULL, NULL, 'Sechs Jahre zwischen der ersten verpflichtenden Kohorte (Nov. 2025) und der vollständigen Einführung (Apr. 2031) gehören zu den längsten Einführungszeiträumen in diesem Tracker — Singapur scheint eine reibungslose Einführung der Geschwindigkeit vorzuziehen.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🐢 Un délai délibérément long', NULL, NULL, 'Six ans entre la première cohorte obligatoire (nov. 2025) et le déploiement complet (avr. 2031) figurent parmi les périodes d''introduction progressive les plus longues de ce tracker — Singapour semble privilégier une adoption harmonieuse plutôt que la rapidité.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔄 De 4 esquinas a 5 esquinas es un cambio de arquitectura genuino', NULL, NULL, 'La incorporación de la IRAS como "5ª esquina" no estaba en el diseño original de InvoiceNow de 2019 — representa la evolución de Singapur de una red de intercambio voluntaria a una red de reporte fiscal a lo largo del tiempo, en lugar de construir un sistema de compensación desde cero.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔄 Von 4-Corner zu 5-Corner ist ein echter Architekturwandel', NULL, NULL, 'Die Aufnahme der IRAS als "5. Ecke" war nicht im ursprünglichen InvoiceNow-Design von 2019 vorgesehen — sie repräsentiert Singapurs Entwicklung von einem freiwilligen Austauschnetzwerk zu einem steuerlichen Meldenetzwerk im Laufe der Zeit, statt ein Clearing-System von Grund auf neu zu bauen.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔄 Passer de 4 coins à 5 coins est un véritable changement d''architecture', NULL, NULL, 'L''ajout de l''IRAS comme « 5e coin » ne figurait pas dans la conception originale d''InvoiceNow de 2019 — cela représente l''évolution de Singapour d''un réseau d''échange volontaire vers un réseau de déclaration fiscale au fil du temps, plutôt que la construction d''un système de contrôle à partir de zéro.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '💰 Apoyo transitorio disponible', NULL, NULL, 'Las subvenciones gubernamentales han apoyado históricamente los costes de adopción de InvoiceNow — vale la pena consultar los esquemas actuales de la IMDA/IRAS si el coste es una barrera para la adopción temprana.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '💰 Übergangsförderung verfügbar', NULL, NULL, 'Staatliche Zuschüsse haben historisch die Einführungskosten von InvoiceNow unterstützt — es lohnt sich, die aktuellen IMDA-/IRAS-Programme zu prüfen, wenn Kosten ein Hindernis für eine frühe Einführung darstellen.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '💰 Un soutien transitoire disponible', NULL, NULL, 'Des subventions gouvernementales ont historiquement soutenu les coûts d''adoption d''InvoiceNow — il vaut la peine de vérifier les dispositifs actuels de l''IMDA/l''IRAS si le coût constitue un frein à une adoption précoce.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🌏 Liderazgo regional en Peppol', NULL, NULL, 'Como la primera Autoridad Peppol fuera de Europa, la experiencia de InvoiceNow de Singapur ha informado directamente cómo mercados Peppol de Asia-Pacífico más recientes, como Malasia y Japón, han abordado sus propios despliegues.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🌏 Regionale Peppol-Führungsrolle', NULL, NULL, 'Als erste Peppol-Autorität außerhalb Europas hat Singapurs InvoiceNow-Erfahrung direkt beeinflusst, wie neuere Peppol-Märkte im asiatisch-pazifischen Raum wie Malaysia und Japan ihre eigenen Einführungen angegangen sind.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🌏 Leadership Peppol régional', NULL, NULL, 'En tant que première autorité Peppol hors d''Europe, l''expérience InvoiceNow de Singapour a directement influencé la manière dont des marchés Peppol plus récents en Asie-Pacifique, comme la Malaisie et le Japon, ont abordé leurs propres déploiements.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'IRAS — Requisito GST InvoiceNow' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Singapore' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'IRAS — GST-InvoiceNow-Anforderung' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Singapore' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'IRAS — Exigence GST InvoiceNow' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Singapore' AND dp.sort_order = 0;
